import {
  AUTH_HTTP_ERROR,
  AUTH_SESSION_ERROR,
  AUTH_COOKIE_ERROR,
  AUTH_SUCCESS
} from '../actions/authActions';

const initialState = {
  authErrorMessage: null,
  errorAlertText: null,
  showErrorAlert: false
};

export default function authReducer(state = initialState, action) {
  
  switch(action.type) {

    case AUTH_HTTP_ERROR:
      
      return {
        ...state,
        authErrorMessage: action.error,
        errorAlertText: "API error. Please try again later.",
        showErrorAlert: true   
      };

    case AUTH_SESSION_ERROR:

      return {
        ...state,
        authErrorMessage: action.error,
        errorAlertText: "Session error. Please try again later.",
        showErrorAlert: true
      };
      
    case AUTH_COOKIE_ERROR:

      return {
        ...state,
        authErrorMessage: action.error,
        errorAlertText: "Cookie error. Please try again later.",
        showErrorAlert: true
      };
      
      case AUTH_SUCCESS:

      return {
        ...state,
        authErrorMessage: null,
        errorAlertText: null,
        showErrorAlert: false
      };
      
      
    default:
      // ALWAYS have a default case in a reducer
      return state;
  }
}
